INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(39411, 'Malachi 1:8', 'Malachi', 1, 8, 'کله چې تاسو ړاندۀ څاروى د قربانۍ دپاره راولئ، آيا دا غلط کار نۀ دے؟ کله چې تاسو ګوډ يا بيمار څاروى قربانى کوئ، آيا دا غلط کار نۀ دے څۀ؟ کۀ تاسو دا کوشش وکړئ چې دا خپل حکمران ته پېش کړئ، آيا هغه به تاسو نه خوشحاله شى څۀ؟ آيا هغه به تاسو قبول کړى؟“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_8.mp3', '', 1761754199, 1761754199),
(39412, 'Malachi 1:9', 'Malachi', 1, 9, '”اوس خُدائ پاک ته سوال زارى کوئ چې په مونږ مهربان شى. ستاسو نه په داسې قربانۍ پېش کولو، آيا هغه به تاسو قبول کړى؟“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_9.mp3', '', 1761754199, 1761754199),
(39413, 'Malachi 1:10', 'Malachi', 1, 10, '”اے کاش چې په تاسو کښې يو کس د عبادتخانې دروازې بندې کړى، نو چې تاسو نور بې‌فائدې اور زما په قربان‌ګاه بل نۀ کړئ. زۀ تاسو نه خوشحاله نۀ يم،“ مالِک خُدائ ربُ الافواج فرمائى، ”او زۀ به ستاسو د لاسونو نه نذرانې قبولې نۀ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_10.mp3', '', 1761754199, 1761754199),
(39414, 'Malachi 1:11', 'Malachi', 1, 11, 'زما نوم به د قومونو په مينځ کښې عظيم وى، د نمر راختو نه تر نمر پرېوتو پورې. په هر ځائ کښې به خوشبودارې او پاکې نذرانې ما ته راوړے شى، ځکه چې زما نوم به د قومونو په مينځ کښې عظيم وى،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_11.mp3', '', 1761754199, 1761754199),
(39415, 'Malachi 1:12', 'Malachi', 1, 12, '”خو تاسو زما د نوم بې‌حرمتى کوئ په دې وئيلو سره چې د مالِک خُدائ قربان‌ګاه ناپاکه ده، او د دې خوراک بې‌اهميته دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_12.mp3', '', 1761754199, 1761754199),
(39416, 'Malachi 1:13', 'Malachi', 1, 13, 'او تاسو وايئ چې، دا څومره بوج دے. او پوکى وهئ او د دې نه نفرت کوئ،“ مالِک خُدائ ربُ الافواج فرمائى. ”کله چې تاسو د غلا، ګوډ يا بيمار څاروى راولئ او د قربانۍ په طور يې پېش کړئ، آيا زۀ دا ستاسو د لاسونو نه قبول کړم څۀ؟“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_13.mp3', '', 1761754199, 1761754199),
(39417, 'Malachi 1:14', 'Malachi', 1, 14, '”لعنت دې وى په هغه دوکه باز باندې چې په رمه کښې يې څُرب نر څاروے وى او نذرونه يې منلې وى، خو مالِک ته مات ګوډ څاروے قربانى کړى.“ نو مالِک خُدائ ربُ الافواج فرمائى چې، ”زۀ لوئ بادشاه يم، او په قومونو کښې خلق زما د نوم نه يريږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_14.mp3', '', 1761754199, 1761754199),
(39418, 'Job 8:1', 'Job', 8, 1, 'بيا بِلداد شوحى ووئيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_1.mp3', '', 1761754199, 1761754199),
(39419, 'Job 8:2', 'Job', 8, 2, '”ترڅو پورې به تۀ دا خبرې کوې، او دا بک بک به جارى ساتې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_2.mp3', '', 1761754199, 1761754199),
(39420, 'Job 8:3', 'Job', 8, 3, 'خُدائ پاک د اِنصاف نه نۀ اوړى. او د قادر خُدائ کارونه همېشه په حقه وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_3.mp3', '', 1761754199, 1761754199),
(39421, 'Job 8:4', 'Job', 8, 4, 'کۀ ستاسو بچو د هغۀ خِلاف ګناه کړې وى، نو هغوئ ته به د هغې بدله مِلاو شوې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_4.mp3', '', 1761754199, 1761754199),
(39422, 'Job 8:5', 'Job', 8, 5, 'کۀ تۀ خُدائ پاک ولټوې او قادر خُدائ ته په دُعا کښې سوال وکړې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_5.mp3', '', 1761754199, 1761754199),
(39423, 'Job 8:6', 'Job', 8, 6, 'کۀ تۀ صفا او صادق يې، نو هغه به په خپله راپاڅى او هغه به تا له خپل صحيح مقام واپس درکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_6.mp3', '', 1761754199, 1761754199),
(39424, 'Job 8:7', 'Job', 8, 7, 'اګر چې ستا شروع معمولى شان وه، خو په مستقبل کښې به مالدار شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_7.mp3', '', 1761754199, 1761754199),
(39425, 'Job 8:8', 'Job', 8, 8, 'معلوماتو دپاره مخکښېنو نسلونو نه تپوس وکړه، او د هغوئ چې کومې تجربې دى په هغې غور وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_8.mp3', '', 1761754199, 1761754199),
(39426, 'Job 8:9', 'Job', 8, 9, 'ځکه چې مونږ پرون پېدا شوى يُو او مونږ ته هيڅ پته نۀ لګى، ځکه چې په زمکه باندې زمونږ وخت د سورى په شان روان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_9.mp3', '', 1761754199, 1761754199),
(39427, 'Job 8:10', 'Job', 8, 10, 'خو پرېږده چې هوښيار مشران درته ښودنه وکړى، او د هغوئ وېنا ته غوږ نيسه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_10.mp3', '', 1761754199, 1761754199),
(39428, 'Job 8:11', 'Job', 8, 11, 'چرته چې اوبۀ نۀ وى نو هلته لوخه نۀ را شنه کيږى، دا د اوبو نه بغېر نۀ کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_11.mp3', '', 1761754199, 1761754199),
(39429, 'Job 8:12', 'Job', 8, 12, 'او دا لا شنه وى او رېبلے شوې نۀ وى، خو د نورو واښو نه زر وچيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_12.mp3', '', 1761754199, 1761754199),
(39430, 'Job 8:13', 'Job', 8, 13, 'نو چې څوک خُدائ پاک هېروى نو د هغوئ هم دغه لار ده، چې څوک د خُدائ نه منکر وى نو د هغوئ اُميد به ختم شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_13.mp3', '', 1761754199, 1761754199),
(39431, 'Job 8:14', 'Job', 8, 14, 'د هغوئ ايمان نازک وى، د هغوئ يقين د جولا د جالې په شان وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_14.mp3', '', 1761754199, 1761754199),
(39432, 'Job 8:15', 'Job', 8, 15, 'چې څوک په دې جاله يقين کوى نو هغوئ ته به دا جاله ټينګه نۀ شى، کۀ څوک ورپورې ځان وتړى، نو دا به يې برداشت نۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_15.mp3', '', 1761754199, 1761754199),
(39433, 'Job 8:16', 'Job', 8, 16, 'منکر کسان داسې ښکارى چې په نمر کښې رازرغون وى، او د دې څانګې په باغ کښې خورې ورې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_16.mp3', '', 1761754199, 1761754199),
(39434, 'Job 8:17', 'Job', 8, 17, 'د هغوئ جرړې د کاڼو د ډېرى نه تاويږى، او دا کاڼى کلک نيسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_17.mp3', '', 1761754199, 1761754199),
(39435, 'Job 8:18', 'Job', 8, 18, 'خو کۀ هغوئ د خپل ځائ نه لرې کړے شى، نو بيا به هغوئ اِنکار وکړى او وائى به چې ما تاسو کله هم نۀ يې ليدلے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_18.mp3', '', 1761754199, 1761754199),
(39436, 'Job 8:19', 'Job', 8, 19, 'ګوره، د هغوئ خوشحالى به د لږ وخت دپاره وى، خو نور بوټى راشنۀ شى او د دې ځائ ونيسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_19.mp3', '', 1761754199, 1761754199),
(39437, 'Job 8:20', 'Job', 8, 20, 'ګوره، خُدائ پاک به يو بې‌داغه کس نۀ رد کوى، او نۀ به د بدعمله خلقو مدد وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_20.mp3', '', 1761754199, 1761754199),
(39438, 'Job 8:21', 'Job', 8, 21, 'هغه به بيا هم تاسو له خوشحالى درکړى، او ستاسو خولې به د خندا نۀ ډکې کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_21.mp3', '', 1761754199, 1761754199),
(39439, 'Job 8:22', 'Job', 8, 22, 'چې څوک ستا نه نفرت کوى نو هغوئ به په شرمونو وشرميږى، او د بدکارانو کور به تباه شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job8_verse_22.mp3', '', 1761754199, 1761754199),
(39440, 'Ezekiel 32:1', 'Ezekiel', 32, 1, 'زمونږ د جلاوطنۍ د دولسم کال د دولسمې میاشتې په لومړۍ ورځ څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_1.mp3', '', 1761754199, 1761754199),
(39441, 'Ezekiel 32:2', 'Ezekiel', 32, 2, '«ای فاني انسانه، د مصر د پاچا فرعون دپاره د وېر سندره ووایه. هغه ته زما له خوا دا پیغام ورسوه: ‹نورو قومونو منځ کې ګڼې خپل ځان لکه زمري په شان خو په رښتیا یې د بحیرې د بلا په شان ته اوبه شړپوې خپلو سیندونو کې ته اوبه خړوې په خپلو پښو باندې او چټلوې سیندونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_2.mp3', '', 1761754199, 1761754199),
(39442, 'Ezekiel 32:3', 'Ezekiel', 32, 3, 'څښتن تعالی داسې وایي: زه به په تا باندې خپل جال کړم خپور د ډېرو قومونو په مرسته به دې غاړې ته راکاږم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_3.mp3', '', 1761754199, 1761754199),
(39443, 'Ezekiel 32:4', 'Ezekiel', 32, 4, 'تا به وغورځوم ځمکه باندې تا به ګوزار کړم په میدان باندې زه به راوړم ټول مرغان د نړۍ چې کښېني تا باندې حیوانات به راوغواړم زه چې ماړه شي په تا باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_4.mp3', '', 1761754199, 1761754199),
(39444, 'Ezekiel 32:5', 'Ezekiel', 32, 5, 'زه به په غرونو کې خپره کړمه ستا غوښه زه به ډکې کړم درې ستا په هډوکو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_5.mp3', '', 1761754199, 1761754199),
(39445, 'Ezekiel 32:6', 'Ezekiel', 32, 6, 'تر غرونو پورې به لمده کړم ځمکه ستا په وینو باندې شي به ډکې درې ورباندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_6.mp3', '', 1761754199, 1761754199),
(39446, 'Ezekiel 32:7', 'Ezekiel', 32, 7, 'کله چې مړه کړم ستا د ژوند شمع زه به پټ کړم اسمانونه پټ به کړم ستوري په تیاره کې لمر به پټ کړمه په ورېځو کې سپوږمۍ به نه کوي رڼا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_7.mp3', '', 1761754199, 1761754199),
(39447, 'Ezekiel 32:8', 'Ezekiel', 32, 8, 'زه به ټولې رڼاګانې د اسمان کړم تیاره راولم به ستا وطن باندې تیاره ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_8.mp3', '', 1761754199, 1761754199),
(39448, 'Ezekiel 32:9', 'Ezekiel', 32, 9, 'کله چې زه ستاسو د بربادۍ خبر په هغو وطنونو کې چې تاسو یې نه پېژنئ، خپور کړم، نو د ډېرو قومونو د خلکو زړونه به خفه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_9.mp3', '', 1761754199, 1761754199),
(39449, 'Ezekiel 32:10', 'Ezekiel', 32, 10, 'کوم کار چې زه به یې ستا سره کوم په هغه باندې به ډېر قومونه ولړزیږي. کله چې زه خپله توره وخوځوم، نو پاچاهان به له وېرې ورپیږي. په کومه ورځ چې ته سقوط وکړې، نو هغوی ټول به د خپل ژوند په خاطر له وېرې لړزیږي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_10.mp3', '', 1761754199, 1761754199),
(39450, 'Ezekiel 32:11', 'Ezekiel', 32, 11, 'څښتن تعالی د مصر پاچا ته داسې وایي: ‹ته به د بابل پاچا د تورې سره مخامخ شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_11.mp3', '', 1761754199, 1761754199),
(39451, 'Ezekiel 32:12', 'Ezekiel', 32, 12, 'زه به د ډېر ظالم قوم غښتلي عسکر ولېږم چې په تا باندې حمله وکړي. بيا به ستا ډېر خلک په جنګ کې ووژل شي. له منځه به یوسي هغوی غرور د مصر له منځه به لاړ شي ټول خلک د مصر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_12.mp3', '', 1761754199, 1761754199),
(39452, 'Ezekiel 32:13', 'Ezekiel', 32, 13, 'زه به حلالې کړم ستا ټولې پادې چې څریږي د ویالو په غاړه هلته به نه وي نور انسان یا حیوان چې کړي چټلې اوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_13.mp3', '', 1761754199, 1761754199),
(39453, 'Ezekiel 32:14', 'Ezekiel', 32, 14, 'هو، زه به کړم صافې ستا اوبه ستا سیندونه به روان کړم ارام ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_14.mp3', '', 1761754199, 1761754199),
(39454, 'Ezekiel 32:15', 'Ezekiel', 32, 15, 'کله چې زه کړم مصر وران او ویجاړ او ټولو شیانو نه یې کړمه خالي کله چې ووژنم ټول اوسېدونکي یې نو شي به پوه هغوی چې زه څښتن یم›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_15.mp3', '', 1761754199, 1761754199),
(39455, 'Ezekiel 32:16', 'Ezekiel', 32, 16, 'پورته سندره به د ویر د یوې سندرې په توګه وویلی شي. د ټولو قومونو ښځې به د ویر دا سندره په مصر او د هغه په ټولو اوسېدونکو باندې د ویر کولو په وخت کې ووایي. ما څښتن تعالی داسې ویلي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_16.mp3', '', 1761754199, 1761754199),
(39456, 'Ezekiel 32:17', 'Ezekiel', 32, 17, 'زمونږ د جلاوطنۍ د دولسم کال د دولسمې میاشتې په پنځلسمه ورځ څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_17.mp3', '', 1761754199, 1761754199),
(39457, 'Ezekiel 32:18', 'Ezekiel', 32, 18, '«ای فاني انسانه، د مصر د ټولو خلکو په خاطر ویر وکړه. هغوی د دنیا د نورو قوي قومونو سره د ځمکې لاندې د مړو دنیا ته ولېږه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_18.mp3', '', 1761754199, 1761754199),
(39458, 'Ezekiel 32:19', 'Ezekiel', 32, 19, 'هغوی ته ووایه: ‹تاسو فکر کوئ چې زیات ښایسته یئ د نورو څخه؟ تاسو به لاړ شئ د مړو دنیا ته یئ به پراته بې دینه خلکو سره›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_19.mp3', '', 1761754199, 1761754199),
(39459, 'Ezekiel 32:20', 'Ezekiel', 32, 20, 'د مصر خلک به د هغو خلکو په شان له منځه لاړ شي چې په جنګ کې وژل شوي دي. د هغوی د ټولو د وژلو دپاره توره تیاره ده. د مصر ډېر خلک به د وژنې دپاره بوتلل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_20.mp3', '', 1761754199, 1761754199),
(39460, 'Ezekiel 32:21', 'Ezekiel', 32, 21, 'غښتلي جنګیالي به د مړو له دنیا څخه د مصریانو او د هغوی د ملاتړو په اړه ووایي: ‹هغه بې‌دینه خلک چې په جنګ کې وژل شوي دي، هغوی راغلي دي او دلته پراته دي!›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_21.mp3', '', 1761754199, 1761754199),
(39461, 'Ezekiel 32:22', 'Ezekiel', 32, 22, 'آشور هلته دی او شاوخوا ته یې د خپلو هغو عسکرو قبرونه دي چې په جنګ کې وژل شوي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_22.mp3', '', 1761754199, 1761754199),
(39462, 'Ezekiel 32:23', 'Ezekiel', 32, 23, 'او د هغوی قبرونه د مړو د دنیا په ډېره ژوره کنده کې پراته دي. د هغه ټول عسکر په جنګ کې وژل شوي دي او د هغوی قبرونه د ده د قبر شاوخوا پراته دي. کله چې هغوی ژوندي وو، نو هغوی به خلک سخت وېرول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_23.mp3', '', 1761754199, 1761754199),
(39463, 'Ezekiel 32:24', 'Ezekiel', 32, 24, 'عیلام هم هلته دی او د هغه ټول عسکر د هغه د قبر شاوخوا پراته دي. هغوی ټول په جنګ کې وژل شوي وو او د مړو دنیا ته بې‌دینه لاړل. کله چې هغوی ژوندي وو، نو هغوی به نور قومونه سخت وېرول، خو اوس هغوی د هغو خلکو په شان چې د هغوی څخه مخکې مړه شوي وو، مړه او شرمېدلي پراته دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_24.mp3', '', 1761754199, 1761754199),
(39464, 'Ezekiel 32:25', 'Ezekiel', 32, 25, 'عیلام د هغو خلکو په منځ کې پروت دی چې په جنګ کې وژل شوي دي او شاوخوا ته یې د خپلو عسکرو قبرونه دي. هغوی ټول بې‌دینه وو او په جنګ کې وژل شوي وو. کله چې هغوی ژوندي وو، نو هغوی به په خلکو کې وېره خپروله، خو اوس هغوی مړه او شرمېدلي پراته دي او د هغو خلکو په سرنوشت باندې اخته دي چې په جنګ کې وژل شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_25.mp3', '', 1761754199, 1761754199),
(39465, 'Ezekiel 32:26', 'Ezekiel', 32, 26, 'د ماشک او توبال د عسکرو قبرونه هم هلته دي. هغوی ټول بې‌دینه وو او په جنګ کې وژل شوي وو، ځکه کله چې هغوی ژوندي وو، نو هغوی به خلک سخت وېرول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_26.mp3', '', 1761754199, 1761754199),
(39466, 'Ezekiel 32:27', 'Ezekiel', 32, 27, 'هغوی د پخوا زمانې د جنګیالیو په شان په قدر او عزت نه وو ښخ شوي. هغه جنګیالي د خپلو وسلو سره د مړو دنیا ته لاړل. د هغوی تورې د هغوی د سرونو لاندې ایښې وې او سپرونه یې په مړو باندې پراته وو. کله چې دا جنګیالي ژوندي وو، نو هغوی به خلک سخت وېرول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_27.mp3', '', 1761754199, 1761754199),
(39467, 'Ezekiel 32:28', 'Ezekiel', 32, 28, 'نو تاسو مصریان به د هغو بې‌دینه خلکو په منځ کې ټوټې ټوټې پراته یئ، کوم چې په جنګ کې وژل شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_28.mp3', '', 1761754199, 1761754199),
(39468, 'Ezekiel 32:29', 'Ezekiel', 32, 29, 'د ادوم د پاچاهانو او نورو ټولو واکمنانو قبرونه هم هلته دي. هغوی قوي عسکر وو، خو اوس هغوی د هغو بې‌دینه خلکو سره چې په جنګ کې وژل شوي وو، د مړو په دنیا کې پراته دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_29.mp3', '', 1761754199, 1761754199),
(39469, 'Ezekiel 32:30', 'Ezekiel', 32, 30, 'د شمال د ټولو مشرانو او د صیدونیانو قبرونه هم هلته دي. د هغوی زور به په یو وخت کې د خلکو د سختې وېرې سبب کېده، خو اوس هغوی په شرم او رسوایۍ سره د هغو خلکو سره چې په جنګ کې وژل شوي دي، د مړو دنیا ته لاړل او بې‌دینه پراته دي. هغوی د هغو خلکو سره په شرم او رسوایۍ کې شریک شول چې د مړو دنیا ته تللي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_30.mp3', '', 1761754199, 1761754199),
(39470, 'Ezekiel 32:31', 'Ezekiel', 32, 31, 'څښتن تعالی داسې وایي: ‹کله چې فرعون او د هغه لښکر هغوی وویني، نو هغوی ته به دا تسلي راپیدا شي چې یوازې د هغوی عسکر نه دي وژل شوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_31.mp3', '', 1761754199, 1761754199),
(39471, 'Ezekiel 32:32', 'Ezekiel', 32, 32, 'ما په فرعون باندې خلک وېرول، خو هغه او د هغه ټولې لښکرې به ووژل شي او د هغو نورو ټولو بې‌دینه خلکو سره به ښخ شي چې په جنګ کې وژل شوي دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel32_verse_32.mp3', '', 1761754199, 1761754199),
(39472, 'Deuteronomy 5:1', 'Deuteronomy', 5, 1, 'موسی د اسراییلو ټول قوم راوغوښت او ورته ویې ویل: «ای د اسراییلو خلکو، هغو ټولو قوانینو ته غوږ ونیسئ چې زه یې نن تاسو ته درکوم. هغه زده کړئ او په غور سره د هغو څخه پیروي وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_1.mp3', '', 1761754199, 1761754199),
(39473, 'Deuteronomy 5:4', 'Deuteronomy', 5, 4, 'څښتن په هماغه غره باندې د اور د منځ څخه ستاسو سره مخامخ خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_4.mp3', '', 1761754199, 1761754199),
(39474, 'Deuteronomy 5:5', 'Deuteronomy', 5, 5, 'په هغه وخت کې زه ستاسو او څښتن ترمنځ ودرېدم چې د هغه خبرې تاسو ته ورسوم، ځکه چې تاسو د هغه اور څخه وېرېدلئ او غره ته نه ورختلئ. څښتن وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_5.mp3', '', 1761754199, 1761754199),
(39475, 'Deuteronomy 5:6', 'Deuteronomy', 5, 6, '‹زه ستاسو څښتن خدای یم چې تاسو مې د مصر څخه چې په کې غلامان وئ راوویستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_6.mp3', '', 1761754199, 1761754199),
(39476, 'Deuteronomy 5:7', 'Deuteronomy', 5, 7, 'زما څخه پرته د بل خدای عبادت مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_7.mp3', '', 1761754199, 1761754199),
(39477, 'Deuteronomy 5:8', 'Deuteronomy', 5, 8, 'د خپلو ځانونو دپاره د هېڅ شي په شکل چې هغه په اسمان کې یا په ځمکه باندې یا د ځمکې لاندې په اوبو کې وي، بتان مه جوړوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_8.mp3', '', 1761754199, 1761754199),
(39478, 'Deuteronomy 5:9', 'Deuteronomy', 5, 9, 'هېڅ بت ته سجده یا عبادت مه کوئ، ځکه چې زه ستاسو څښتن خدای یو غیرتي خدای یم. څوک چې زما څخه کرکه کوي، زه به هغوی او د هغوی اولادې ته تر درېم او څلورم نسله پورې سزا ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_9.mp3', '', 1761754199, 1761754199),
(39479, 'Deuteronomy 5:10', 'Deuteronomy', 5, 10, 'خو زه د هغو زرګونو نسلونو سره چې زما سره مینه کوي او زما حکمونو ته غاړه ږدي، مینه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_10.mp3', '', 1761754199, 1761754199),
(39480, 'Deuteronomy 5:11', 'Deuteronomy', 5, 11, 'زما نوم د بدو مقصدونو دپاره مه کاروئ، ځکه چې زه ستاسو څښتن خدای به هغه چاته سزا ورکړم چې زما نوم په غلطه وکاروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_11.mp3', '', 1761754199, 1761754199),
(39481, 'Deuteronomy 5:12', 'Deuteronomy', 5, 12, 'لکه څنګه چې ما یعنې ستاسو څښتن خدای په تاسو باندې امر کړی دی، د سبت ورځ ولمانځئ او هغه سپېڅلې وګڼئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_12.mp3', '', 1761754199, 1761754199),
(39482, 'Deuteronomy 5:13', 'Deuteronomy', 5, 13, 'تاسو د کار کولو دپاره شپږ ورځې لرئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_13.mp3', '', 1761754199, 1761754199),
(39483, 'Deuteronomy 5:14', 'Deuteronomy', 5, 14, 'خو اوومه ورځ د ارام کولو ورځ ده چې څښتن خدای ته وقف شوې ده. په دې ورځ به تاسو هېڅ کار نه کوئ، نه تاسو، نه ستاسو زامن یا لورګانې، نه غلامان، نه ستاسو غویان یا خره یا نور حیوانات او نه هغه پردي خلک چې ستاسو په وطن کې اوسیږي. ستاسو غلامان باید ستاسو په شان استراحت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_14.mp3', '', 1761754199, 1761754199),
(39484, 'Deuteronomy 5:15', 'Deuteronomy', 5, 15, 'دا په یاد ولرئ چې تاسو په مصر کې غلامان وئ او ما یعنې ستاسو څښتن خدای په خپل قوي مټ او ټول قدرت سره ازاد کړئ. نو ځکه تاسو ته حکم کوم چې د سبت یعنې د ارام کولو ورځ لمانځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_15.mp3', '', 1761754199, 1761754199),
(39485, 'Deuteronomy 5:16', 'Deuteronomy', 5, 16, 'لکه څنګه چې زه یعنې ستاسو څښتن خدای تاسو ته حکم کوم چې د خپل مور او پلار عزت کوئ، ترڅو نېکمرغه اوسئ او په هغه خاوره کې چې زه یې درکوم زیات عمر ولرئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_16.mp3', '', 1761754199, 1761754199),
(39486, 'Deuteronomy 5:17', 'Deuteronomy', 5, 17, 'قتل مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_17.mp3', '', 1761754199, 1761754199),
