(39488, 'Deuteronomy 5:19', 'Deuteronomy', 5, 19, 'غلا مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_19.mp3', '', 1761754199, 1761754199),
(39489, 'Deuteronomy 5:20', 'Deuteronomy', 5, 20, 'د هېچا په خلاف د دروغو شاهدي مه ورکوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_20.mp3', '', 1761754199, 1761754199),
(39490, 'Deuteronomy 5:21', 'Deuteronomy', 5, 21, 'د بل سړي ښځې ته د تمې په سترګه مه ګورئ. د هغه کور، ځمکې، غلامانو، غویانو، خرو یا هرڅه چې هغه یې لري، ورته تمه مه کوئ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_21.mp3', '', 1761754199, 1761754199),
(39491, 'Deuteronomy 5:22', 'Deuteronomy', 5, 22, 'دا هغه حکمونه دي چې څښتن په هغه وخت کې تاسو ټولو ته درکړل کله چې د سینا د غره تر څنګ راټول شوي وئ او هغه په لوړ اواز سره د اور او تورې ورېځې د منځ څخه خبرې وکړې. هغه نور څه نه بلکې همدا حکمونه راکړل. بیا یې هغه د تیږو په دوو لوحو باندې ولیکل او ماته یې راکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_22.mp3', '', 1761754199, 1761754199),
(39492, 'Deuteronomy 5:23', 'Deuteronomy', 5, 23, 'کله چې ټول غره اور واخیست او تاسو هغه غږ واورېد چې د تیارې څخه راتله، نو ستاسو مشران او ستاسو د قبیلو مشران ماته راغلل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_23.mp3', '', 1761754199, 1761754199),
(39493, 'Deuteronomy 5:24', 'Deuteronomy', 5, 24, 'او ویې ویل: ‹کله چې مونږ د هغه خبرې واورېدلې چې د اور د منځ څخه یې کولې، مونږ ته خپل څښتن خدای خپله لویي او جلال راوښود! نن مونږ ولیدل چې د یو انسان دپاره که خدای ورسره خبرې هم کړې وي، دا ممکنه ده چې ژوندی پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_24.mp3', '', 1761754199, 1761754199),
(39494, 'Deuteronomy 5:25', 'Deuteronomy', 5, 25, 'خو مونږ ولې خپل ځانونه د مرګ په خطر کې واچوو؟ هغه هیبتناکه اور به مونږ له منځه یوسي. مونږ یقین لرو که چېرې د خپل څښتن خدای غږ بیا واورو، نو مړه به شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_25.mp3', '', 1761754199, 1761754199),
(39495, 'Deuteronomy 5:26', 'Deuteronomy', 5, 26, 'ایا داسې یو انسان چې د اور د منځ څخه یې د ژوندي خدای خبرې اورېدلې وي، کله ژوندی پاتې شوی دی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_26.mp3', '', 1761754199, 1761754199),
(39496, 'Deuteronomy 5:27', 'Deuteronomy', 5, 27, 'نو موسی، نژدې ورشه او زمونږ د څښتن خدای ټولو خبرو ته غوږ ونیسه. بیا بېرته راشه او هغه خبرې چې هغه درته وکړلې مونږ ته یې ووایه. مونږ به ورته غوږ ونیسو او وبه یې منو.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_27.mp3', '', 1761754199, 1761754199),
(39497, 'Deuteronomy 5:28', 'Deuteronomy', 5, 28, 'کله چې څښتن دا خبرې واورېدلې، هغه ماته وویل: ‹ما د دغو خلکو خبرې واورېدلې، هغوی رښتیا وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_28.mp3', '', 1761754199, 1761754199),
(39498, 'Deuteronomy 5:29', 'Deuteronomy', 5, 29, 'کاشکې هغوی تل داسې احساس ولري! کاشکې هغوی تل زما څخه ووېریږي او زما ټولو حکمونو ته غاړه کېږدي، ترڅو د تل دپاره د هغوی او د هغوی د اولادې هر کار سم وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_29.mp3', '', 1761754199, 1761754199),
(39499, 'Deuteronomy 5:30', 'Deuteronomy', 5, 30, 'لاړ شه او هغوی ته ووایه چې بېرته خپلو خېمو ته ورستانه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_30.mp3', '', 1761754199, 1761754199),
(39500, 'Deuteronomy 5:31', 'Deuteronomy', 5, 31, 'خو موسی، ته دلته زما سره پاتې شه. زه به تاته خپل ټول قوانین او حکمونه درکړم. هغه قوم ته ورزده کړه، ترڅو هغوی په هغه خاوره کې ورته غاړه کېږدي چې زه یې ورکوم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_31.mp3', '', 1761754199, 1761754199),
(39501, 'Deuteronomy 5:32', 'Deuteronomy', 5, 32, 'د اسراییلو خلکو، تاسو باید په غور سره د خپل څښتن خدای هر حکم په ځای کړئ. د هغه د هېڅ یو قانون څخه سرغړونه ونه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_32.mp3', '', 1761754199, 1761754199),
(39502, 'Deuteronomy 5:33', 'Deuteronomy', 5, 33, 'د هغو ټولو څخه پیروي وکړئ، ترڅو ستاسو ټول کارونه سم روان وي او په هغه وطن کې چې تاسو به یې ونیسئ، خپل ژوند ته دوام ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy5_verse_33.mp3', '', 1761754199, 1761754199),
(39503, 'Psalms 7:1', 'Psalms', 7, 1, 'ای څښتنه، زما خدایه، ما پناه راوړې تاته وژغوره ما خلاص کړه د دوی ټولو راپسې چې دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_1.mp3', '', 1761754199, 1761754199),
(39504, 'Psalms 7:2', 'Psalms', 7, 2, 'هسې نه چې د زمریو په شان مې بوځي هغه ځای ته چې مې څوک د خلاصون نه وي ما به کړي ټوټې ټوټې په هغه ځای کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_2.mp3', '', 1761754199, 1761754199),
(39505, 'Psalms 7:5', 'Psalms', 7, 5, 'نو بیا پرېږده دښمنان مې راپسې شي او ما ګېر کړي کړي پایمال مې او ما مړ کړي هم عزت زما له خاورو سره خاورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_5.mp3', '', 1761754199, 1761754199),
(39506, 'Psalms 7:6', 'Psalms', 7, 6, 'په خپل قهر کې راپورته شه څښتنه! زما د دښمنانو د غضب په وړاندې شه راپورته نو اوس راویښ شه ته زما دپاره برقرار کړه عدالت چې ته یې غواړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_6.mp3', '', 1761754199, 1761754199),
(39507, 'Psalms 7:7', 'Psalms', 7, 7, 'ټول قومونه دې خپل ځان باندې راټول کړه حکومت وکړه په هغو له اسمانه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_7.mp3', '', 1761754199, 1761754199),
(39508, 'Psalms 7:8', 'Psalms', 7, 8, 'ته قاضي یې د ټولو قومونو زما حق کې قضاوت وکړه څښتنه ته پوهېږې چې صادق او بې‌ګناه یم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_8.mp3', '', 1761754199, 1761754199),
(39509, 'Psalms 7:9', 'Psalms', 7, 9, 'خدایه ته عادل یې عدالت کې ته ازمایې زړه او فکر د هرچا د بدکارو د بدیو مخه نیسه اجر ورکړه هغه چاته چې نېکان دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_9.mp3', '', 1761754199, 1761754199),
(39510, 'Psalms 7:10', 'Psalms', 7, 10, 'خدای دی سپر زما هم ژغورونکی د هغو دی چې په زړونو کې صادق وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_10.mp3', '', 1761754199, 1761754199);